from taf.ul.kpi_selector.utilities.kpi_logger import log_suppression
from taf.ul.kpi_selector.operations.operation_prototype.operation_prototype import OperationPrototype


class CellLock(OperationPrototype):
    def __init__(self, bts):
        super(CellLock, self).__init__(bts)
        self.operation_details = {
            "Timeout": 0,
            "Operation": "Cell lock",
            "Start point": "Cell lock request",
            "End point": "Cell down",
            "Requirement": "-",
        }

    def get_kpi(self):
        """
        Gets kpi for cell lock operation.
        :return: dictionary with timeout, requirement and operation description for cell lock
        :rtype: dict
        """
        log_suppression("There was no timeout found in Gates for stream older than 23R1, "
                        "returning default timeout for cell lock. Please, do not base Your pronto "
                        "on that value.")

        self.operation_details["Timeout"] = 60
        return self.operation_details
